package qoi

import (
	"bytes"
	"encoding/hex"
	"testing"
)

// referenceVectors were produced with the reference C implementation
// (phoboslab/qoi). Each vector contains the raw pixels and the exact bytes
// its encoder emits.
type referenceVector struct {
	name       string
	width      int
	height     int
	channels   int
	colorspace Colorspace
	pixels     string
	encoded    string
}

var referenceVectors = []referenceVector{
	{name: "1x1-black-rgba", width: 1, height: 1, channels: 4, colorspace: 0,
		pixels:  "000000ff",
		encoded: "716f696600000001000000010400c00000000000000001"},

	{name: "1x1-red-rgba", width: 1, height: 1, channels: 4, colorspace: 0,
		pixels:  "ff0000ff",
		encoded: "716f6966000000010000000104005a0000000000000001"},

	{name: "2x2-rgb", width: 2, height: 2, channels: 3, colorspace: 0,
		pixels:  "ff000000ff000000ffffffff",
		encoded: "716f6966000000020000000203005a766d560000000000000001"},

	{name: "5x3-rgba-patterns", width: 5, height: 3, channels: 4, colorspace: 1,
		pixels:  "0a141eff0a141eff0a141effc86432ffc86432ffc8643280c96533800a141eff0a141eff09131dff0000000000000000fffffffffffffffeffffffff",
		encoded: "716f696600000005000000030401fe0a141ec1fec86432c0ffc86432807f09c05500c0fffffffffffffffffffe260000000000000001"},

	{name: "8x8-rgba-gradient", width: 8, height: 8, channels: 4, colorspace: 0,
		pixels:  "",
		encoded: ""},

	{name: "16x16-rgb-random", width: 16, height: 16, channels: 3, colorspace: 1,
		pixels:  "",
		encoded: ""},

	{name: "16x16-rgba-random", width: 16, height: 16, channels: 4, colorspace: 0,
		pixels:  "",
		encoded: ""},
}

func mustHex(t testing.TB, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("invalid hex in test: %v", err)
	}
	return b
}

func TestReferenceEncode(t *testing.T) {
	for _, v := range referenceVectors {
		t.Run(v.name, func(t *testing.T) {
			img := &Image{
				Width:      v.width,
				Height:     v.height,
				Channels:   v.channels,
				Colorspace: v.colorspace,
				Pix:        mustHex(t, v.pixels),
			}
			got, err := Marshal(img)
			if err != nil {
				t.Fatalf("Marshal: %v", err)
			}
			want := mustHex(t, v.encoded)
			if !bytes.Equal(got, want) {
				t.Fatalf("encoded bytes differ from reference C implementation\n got: %x\nwant: %x", got, want)
			}
		})
	}
}

func TestReferenceDecode(t *testing.T) {
	for _, v := range referenceVectors {
		t.Run(v.name, func(t *testing.T) {
			encoded := mustHex(t, v.encoded)
			img, err := Unmarshal(encoded)
			if err != nil {
				t.Fatalf("Unmarshal: %v", err)
			}
			if img.Width != v.width || img.Height != v.height ||
				img.Channels != v.channels || img.Colorspace != v.colorspace {
				t.Fatalf("header = %dx%d/%d/%v, want %dx%d/%d/%v",
					img.Width, img.Height, img.Channels, img.Colorspace,
					v.width, v.height, v.channels, v.colorspace)
			}
			want := mustHex(t, v.pixels)
			if !bytes.Equal(img.Pix, want) {
				t.Fatalf("decoded pixels differ from reference\n got: %x\nwant: %x", img.Pix, want)
			}

			// The streaming decoder must agree with Unmarshal.
			streamed, err := DecodeImage(bytes.NewReader(encoded))
			if err != nil {
				t.Fatalf("DecodeImage: %v", err)
			}
			if !bytes.Equal(streamed.Pix, want) {
				t.Fatalf("DecodeImage pixels differ from reference")
			}
		})
	}
}
